package com.smarthospital.controller;
import com.smarthospital.model.User;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/attendance") public class AttendanceServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){List<Map<String,Object>>rows=new ArrayList<>();String scope=Access.isStaff(u)?"s.user_id=?":Access.isAdmin(u)?"1=1":"s.department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id=? AND active=1)";String q="SELECT a.attendance_id,s.staff_id,s.staff_code,s.name,a.attendance_date,a.check_in,a.check_out,a.status FROM attendance a JOIN staff s ON a.staff_id=s.staff_id WHERE "+scope+" ORDER BY a.attendance_date DESC,a.check_in DESC LIMIT 100";try(PreparedStatement p=c.prepareStatement(q)){if(!Access.isAdmin(u))p.setInt(1,u.id());try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new HashMap<>();for(int i=1;i<=8;i++)m.put("c"+i,r.getObject(i));rows.add(m);}}}req.setAttribute("rows",rows);if(!Access.isStaff(u)){String ds=Access.isAdmin(u)?"1=1":"s.department_id IN (SELECT department_id FROM supervisor_departments WHERE supervisor_user_id="+u.id()+" AND active=1)";List<Map<String,Object>>st=new ArrayList<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT s.staff_id,s.staff_code,s.name FROM staff s WHERE s.status='ACTIVE' AND "+ds+" ORDER BY s.name")){while(r.next()){Map<String,Object>m=new HashMap<>();m.put("id",r.getInt(1));m.put("code",r.getString(2));m.put("name",r.getString(3));st.add(m);}}req.setAttribute("staff",st);}req.getRequestDispatcher("/attendance.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){String action=req.getParameter("action");int staff=Access.isStaff(u)?Access.ownStaffId(c,u.id()):Integer.parseInt(req.getParameter("staff_id"));if(!Access.isStaff(u)&&!Access.canAccessStaff(c,u,staff))throw new SecurityException("Staff member is outside your department scope.");if("checkin".equals(action)){try(PreparedStatement p=c.prepareStatement("INSERT INTO attendance(staff_id,attendance_date,check_in,status) VALUES(?,CURDATE(),NOW(),'PRESENT')")){p.setInt(1,staff);p.executeUpdate();}}else if("checkout".equals(action)){int aid=Integer.parseInt(req.getParameter("attendance_id"));try(PreparedStatement p=c.prepareStatement("UPDATE attendance SET check_out=NOW() WHERE attendance_id=? AND staff_id=? AND check_out IS NULL")){p.setInt(1,aid);p.setInt(2,staff);if(p.executeUpdate()==0)throw new IllegalArgumentException("Open attendance record not found.");}}else throw new IllegalArgumentException("Unsupported attendance action.");Audit.log(u.id(),"ATTENDANCE",action+" staff #"+staff);resp.sendRedirect(req.getContextPath()+"/attendance");}catch(Exception e){resp.sendError(400,e.getMessage());}}
}
